{
  "IP": "neorv32_sdi",
  "Conceptual Assets": [
    {
      "Concept ID": "C1",
      "Concept Name": "SDI enable configuration",
      "Unit": "neorv32_sdi",
      "Information": "The enable setting controls whether the SDI subsystem and its receive and transmit paths are active; normal operation depends on it. It enters through the bus write data and is readable through the bus response.",
      "Rubric": {
        "Confidentiality": "no",
        "Integrity": "yes",
        "Availability": "yes",
        "Undermined Expected Behavior": "no"
      },
      "Rubric Reason": "Integrity is at risk because a bus write assigns the setting at line 133, allowing it to be changed. Availability is at risk because the setting clears both FIFOs at lines 200 and 239 and controls serial-engine state at line 296, allowing transfers to be disabled.",
      "Objectives At Risk": [
        "I",
        "A"
      ],
      "Attack": "An attacker able to issue a bus write can clear the FIFOs or disable the serial engine by changing the enable setting.",
      "Enters Through": [
        "bus_req_i.data"
      ],
      "Leaves Through": [
        "bus_rsp_o.data"
      ],
      "Entry Lines": [
        133
      ],
      "Held Lines": [
        117,
        133
      ],
      "Exit Lines": [
        143
      ]
    },
    {
      "Concept ID": "C2",
      "Concept Name": "Transmit serial payload",
      "Unit": "neorv32_sdi",
      "Information": "Payload words written by the host for serial transmission are shifted onto the SDI data output; the transmit function depends on these words.",
      "Rubric": {
        "Confidentiality": "yes",
        "Integrity": "yes",
        "Availability": "yes",
        "Undermined Expected Behavior": "no"
      },
      "Rubric Reason": "Confidentiality is at risk because host data enters at line 201 and is exposed at the serial output at line 345. Integrity is at risk because the transmit word is loaded from the bus/FIFO path at lines 201 and 305 and is shifted by serial logic at line 327. Availability is at risk because the enable setting clears the transmit FIFO at line 200 and chip-select-controlled serial sequencing at line 307 can withhold transmission.",
      "Objectives At Risk": [
        "C",
        "I",
        "A"
      ],
      "Attack": "An attacker can replace a queued transmit word, prevent it from being sent, or observe it at the SDI output.",
      "Enters Through": [
        "bus_req_i.data"
      ],
      "Leaves Through": [
        "sdi_dat_o"
      ],
      "Entry Lines": [
        201
      ],
      "Held Lines": [],
      "Exit Lines": [
        345
      ]
    },
    {
      "Concept ID": "C3",
      "Concept Name": "Received serial payload",
      "Unit": "neorv32_sdi",
      "Information": "Payload words sampled from the serial data input are collected and made available for host reads; the receive function depends on these words.",
      "Rubric": {
        "Confidentiality": "yes",
        "Integrity": "yes",
        "Availability": "yes",
        "Undermined Expected Behavior": "no"
      },
      "Rubric Reason": "Confidentiality is at risk because serial input data enters at line 270 and a received word is returned through the bus response at line 162. Integrity is at risk because sampled bits are shifted into the receive word at line 327 and written into the receive FIFO through lines 235 and 236, so the returned word can be altered. Availability is at risk because the receive FIFO is cleared when enable is inactive at line 239 and receive completion depends on the serial framing conditions at lines 324 and 326.",
      "Objectives At Risk": [
        "C",
        "I",
        "A"
      ],
      "Attack": "An attacker can inject or alter serial bits, clear or block the receive path, or cause received data to be exposed through a bus read.",
      "Enters Through": [
        "sdi_dat_i"
      ],
      "Leaves Through": [
        "bus_rsp_o.data"
      ],
      "Entry Lines": [
        270
      ],
      "Held Lines": [],
      "Exit Lines": [
        162
      ]
    },
    {
      "Concept ID": "C4",
      "Concept Name": "Serial chip-select handshake",
      "Unit": "neorv32_sdi",
      "Information": "The serial chip-select state frames transactions and determines when serial transfers are accepted. The state is sampled from the chip-select input and is also reported in the bus response.",
      "Rubric": {
        "Confidentiality": "no",
        "Integrity": "yes",
        "Availability": "yes",
        "Undermined Expected Behavior": "no"
      },
      "Rubric Reason": "Integrity is at risk because the sampled chip-select value controls serial state transitions at lines 307, 315, and 324, so an altered value can corrupt transaction framing. Availability is at risk because the same conditions can keep the serial engine inactive or terminate a transfer, withholding serial data.",
      "Objectives At Risk": [
        "I",
        "A"
      ],
      "Attack": "An attacker can hold or alter chip select so that transfers are framed incorrectly or prevented from completing.",
      "Enters Through": [
        "sdi_csn_i"
      ],
      "Leaves Through": [
        "bus_rsp_o.data"
      ],
      "Entry Lines": [
        269
      ],
      "Held Lines": [
        275
      ],
      "Exit Lines": [
        160
      ]
    },
    {
      "Concept ID": "C5",
      "Concept Name": "Interrupt notification",
      "Unit": "neorv32_sdi",
      "Information": "The interrupt notification reports FIFO-related conditions to the integrating system so that queued receive or transmit work can be serviced. It has no entry port because it is generated internally from control state and FIFO status.",
      "Rubric": {
        "Confidentiality": "no",
        "Integrity": "yes",
        "Availability": "yes",
        "Undermined Expected Behavior": "no"
      },
      "Rubric Reason": "Integrity is at risk because the registered interrupt output is computed from internal control and FIFO conditions at lines 249 through 254, allowing false or missing notifications. Availability is at risk because the enable term at line 249 can suppress the notification and prevent an interrupt-driven system from servicing queued work.",
      "Objectives At Risk": [
        "I",
        "A"
      ],
      "Attack": "An attacker can cause false interrupts or suppress a required interrupt, preventing the host from servicing SDI transfers.",
      "Enters Through": [],
      "Leaves Through": [
        "irq_o"
      ],
      "Entry Lines": [],
      "Held Lines": [
        247,
        249
      ],
      "Exit Lines": [
        249
      ]
    }
  ],
  "Not Kept": [
    {
      "Candidate Name": "Interrupt-enable configuration",
      "Candidate Unit": "neorv32_sdi",
      "Merged Into": "",
      "Why Not Kept": "It only tunes the interrupt request output and is excluded as a port option by the Port options rule."
    },
    {
      "Candidate Name": "FIFO occupancy and buffer status",
      "Candidate Unit": "neorv32_sdi",
      "Merged Into": "",
      "Why Not Kept": "The status bits only report whether buffered data can move or was lost, so the Buffer and engine status bits rule does not treat them as information of their own."
    },
    {
      "Candidate Name": "Transmit FIFO buffering",
      "Candidate Unit": "neorv32_sdi",
      "Merged Into": "C2",
      "Why Not Kept": ""
    },
    {
      "Candidate Name": "Receive FIFO buffering",
      "Candidate Unit": "neorv32_sdi",
      "Merged Into": "C3",
      "Why Not Kept": ""
    },
    {
      "Candidate Name": "Transmit shift-register staging",
      "Candidate Unit": "neorv32_sdi",
      "Merged Into": "C2",
      "Why Not Kept": ""
    },
    {
      "Candidate Name": "Receive shift-register staging",
      "Candidate Unit": "neorv32_sdi",
      "Merged Into": "C3",
      "Why Not Kept": ""
    },
    {
      "Candidate Name": "Serial engine sequencing state",
      "Candidate Unit": "neorv32_sdi",
      "Merged Into": "",
      "Why Not Kept": "The serial state and bit count only order and pace transfer steps, so Sequencing state bars them as concepts of their own."
    },
    {
      "Candidate Name": "Serial pacing pulses",
      "Candidate Unit": "neorv32_sdi",
      "Merged Into": "",
      "Why Not Kept": "The start and done strobes only pace FIFO transfers and are excluded by the Pacing pulses rule."
    },
    {
      "Candidate Name": "Synchronizer samples",
      "Candidate Unit": "neorv32_sdi",
      "Merged Into": "",
      "Why Not Kept": "The synchronizer registers and derived wires only resample external serial signals, so Working values bars them as independent concepts."
    },
    {
      "Candidate Name": "Bus access command",
      "Candidate Unit": "neorv32_sdi",
      "Merged Into": "",
      "Why Not Kept": "The address, direction, and strobe fields only specify accesses to this unit's registers or FIFOs and are excluded by Access command fields."
    },
    {
      "Candidate Name": "Bus response handshake",
      "Candidate Unit": "neorv32_sdi",
      "Merged Into": "",
      "Why Not Kept": "The acknowledge repeats the request strobe and the error flag is tied to a constant, so Bus handshake copies excludes them as information of their own."
    },
    {
      "Candidate Name": "FIFO size configuration",
      "Candidate Unit": "neorv32_sdi",
      "Merged Into": "",
      "Why Not Kept": "RTX_FIFO and its derived size only fix the build and cannot be changed or withheld at run time, so Build-time values excludes them."
    },
    {
      "Candidate Name": "Serial link clock",
      "Candidate Unit": "neorv32_sdi",
      "Merged Into": "",
      "Why Not Kept": "sdi_clk_i is the serial peer's clock line and is excluded by the Clocks and resets rule."
    }
  ],
  "Notes": []
}
